sp_widget.client_script:
api.controller = function ($location, $timeout, DHManagerService) {

	var c = this;
	c.loading = true;
	c.hasDevices = false;
	c.score = null;
	c.maxScore = 100;

	/* ----------DEV STUFF----------- */
	c.updateGraph = function(score) {
		if (!c.loading) {
			createChart(score);
		} else {
			createChart(0);
		}
	}
	/* --------END DEV STUFF---------- */

	// Scorebounds are the upper limits for a score, e.g. any score less than the value for 'bad' is considered a bad score
	const scoreBounds = {
		bad: 33,
		avg: 66,
	};

	DHManagerService.getDexScores().then((r) => {

		$timeout(() => {

			const scores = r?.data;

			if(!scores || scores.length == 0)
				return;

			const sortedScores = DHManagerService.sortScoresByDate(scores, true);

			c.score = parseInt(sortedScores[0]?.value)?.toFixed();

			createChart(c.score);
			c.loading = false;
		});
	});

	c.$onInit = () => {
		c.hasDevices = c.data.userHasDevices;
	}

	c.getScoreRating = (value) => {
		if (value < scoreBounds.bad) {
			return "bad";
		} else if (value < scoreBounds.avg) {
			return "avg";
		} else {
			return "good";
		}
	};

	c.navToPage = () => {
		$location.search({ id: "dh_digital_experience" });
	};

	function calcSeries(value) {
		if (!value) {
			return null;
		}

		let series = [];

		if (value < scoreBounds.bad) {
			series.push({ data: [parseFloat(value)] });
		} else if (value < scoreBounds.avg) {
			series.push(
				{ data: [scoreBounds.bad] },
				{ data: [value - scoreBounds.bad] }
			);
		} else {
			series.push(
				{ data: [scoreBounds.bad] },
				{ data: [scoreBounds.avg - scoreBounds.bad] },
				{ data: [value - scoreBounds.avg] }
			);
		}

		return series;
	}

	// Calculate the color of the chart based on 
	function calcColors(value) {
		if (!value) {
			return null;
		}

		let colors = [];

		if (c.data.useMultiColors) {
			colors = ["red", "orange", "green"];
		} else if (value < scoreBounds.bad) {
			colors = ["red"];
		} else if (value < scoreBounds.avg) {
			colors = ["orange"];
		} else {
			colors = ["green"];
		}

		return colors;
	}

	function createChart(deviceScore) {
		Highcharts.chart("score-graph", {
			navigation: {
        buttonOptions: {
            enabled: false
        },
			},
			colors: calcColors(deviceScore), //["red", "orange", "green"],
			chart: {
				height: "100%",
				type: "column",
				inverted: true,
				polar: true,
				borderWidth: 0,
				backgroundColor: "transparent",
				toolbar: false,
			},
			title: {
				text: "",
			},
			credits: {
				enabled: false, // Disable the watermark
			},
			tooltip: {
				enabled: false,
			},
			pane: {
				//   size: "100%",
				innerSize: "90%",
				startAngle: -135,
				endAngle: 135,
			},
			xAxis: {
				tickInterval: 1,
				gridLineWidth: 1,
				labels: {
					enabled: false,
				},
				lineWidth: 0,
				categories: ["Score"],
				accessibility: {
					description: "Device Score",
				},
			},
			yAxis: {
				labels: {
					enabled: false,
				},
				crosshair: {
					enabled: false,
				},
				gridLineWidth: 0,
				lineWidth: 0,
				tickInterval: 25,
				reversedStacks: false,
				max: 100,
				accessibility: {
					description: "Device Score",
				},
			},
			plotOptions: {
				column: {
					stacking: "normal",
					borderWidth: 1,
					pointPadding: 1,
					groupPadding: 0.15,
					dataLabels: {
						enabled: false,
					},
				},
			},
			legend: {
				enabled: false, // Disable the legend
			},
			series: calcSeries(deviceScore),
		});
	}

};

sp_widget.css:
.dh-grid-item {
  display: grid;
  grid-template-columns: 50% 50%;
  align-items: center;
  justify-items: center;

  .text-container {
    text-align: center;

    p {
      font-size:large;

      & span {
        font-size: xx-large;

        &.good {color:$brand-success}
        &.avg {color: $brand-warning}
        &.bad {color: $brand-danger}
      }
    }
  }

  .imagery {
    display: grid;
    align-items: center;
    justify-items: center;
    width: 100%;

    &>div {
      grid-area: 1 / 1;
    }

    #score-graph {
      width: 100%;
    }

    .graph-img-container {
      z-index: 1;
      width: 65%;
      max-width: 350px;

      img {
        width: 100%;
      }
    }
  }

  &#no-score-layout {
    > img {
      max-width: 80%;
      max-height: 80%;
    }
  }
}

.heart-rate {
  width: 150px;
  height: 73px;
  position: relative;
  margin: 20px auto;
  scale: 200%;
}

.fade-in {
  position: absolute;
  width: 100%;
  height: 100%;
  background-color: #FFFFFF;
  top: 0;
  right: 0;
  animation: heartRateIn 2.5s linear infinite;
}

.fade-out {
  position: absolute;
  width: 120%;
  height: 100%;
  top: 0;
  left: -120%;
  animation: heartRateOut 2.5s linear infinite;
  background: rgba(255, 255, 255, 1);
  background: -moz-linear-gradient(left, rgba(255, 255, 255, 1) 0%, rgba(255, 255, 255, 1) 50%, rgba(255, 255, 255, 0) 100%);
  background: -webkit-linear-gradient(left, rgba(255, 255, 255, 1) 0%, rgba(255, 255, 255, 1) 50%, rgba(255, 255, 255, 0) 100%);
  background: -o-linear-gradient(left, rgba(255, 255, 255, 1) 0%, rgba(255, 255, 255, 1) 50%, rgba(255, 255, 255, 0) 100%);
  background: -ms-linear-gradient(left, rgba(255, 255, 255, 1) 0%, rgba(255, 255, 255, 1) 50%, rgba(255, 255, 255, 0) 100%);
  background: linear-gradient(to right, rgba(255, 255, 255, 1) 0%, rgba(255, 255, 255, 1) 80%, rgba(255, 255, 255, 0) 100%);
}

@keyframes heartRateIn {
  0% {
    width: 100%;
  }
  50% {
    width: 0;
  }
  100% {
    width: 0;
  }
}

@keyframes heartRateOut {
  0% {
    left: -120%;
  }
  30% {
    left: -120%;
  }
  100% {
    left: 0;
  }
}

sp_widget.script:
(function() {

  var dh = new DeviceHealth();

  data.userHasDevices = dh.userHasDevices();
  data.useMultiColors = options.use_multicolor_chart == 'true'; // Should the chart show a mix of red/amber/green, or just a solid color

})();
